"""统一 API 错误码与 HTTP 异常。

批次 5.10：业务失败不再以 ``200 + success=False`` 返回，而是抛出带稳定
``error_code`` 的 HTTP 异常。前端只需看 HTTP 状态码即可判断失败，再按
``error_code`` 做结构化展示；``detail`` 仍是人类可读字符串，保持旧调用方
（以及 5.3/5.4 的既有断言）兼容。
"""

from __future__ import annotations

from enum import StrEnum
from typing import Any

from fastapi import HTTPException


class ErrorCode(StrEnum):
    """跨路由共享的错误码。

    值使用小写下划线，和 4.3 的分级错误码（``device`` / ``page_drift`` /
    ``ui_version``）保持同一风格。新增错误码只增不改，前端可安全地按
    未知码降级为通用错误。
    """

    # 生命周期 / 任务
    SYSTEM_NOT_READY = 'system_not_ready'
    SYSTEM_STARTING = 'system_starting'
    SYSTEM_STOPPING = 'system_stopping'
    SYSTEM_START_FAILED = 'system_start_failed'
    SYSTEM_STOP_TIMEOUT = 'system_stop_timeout'
    CONFIG_PATH_NOT_FOUND = 'config_path_not_found'
    TASK_RUNNING = 'task_running'
    TASK_STOP_FAILED = 'task_stop_failed'

    # 设备
    DEVICE_BUSY = 'device_busy'
    DEVICE_UNAVAILABLE = 'device_unavailable'
    EMULATOR_QUERY_FAILED = 'emulator_query_failed'

    # 业务操作
    INTENSIFY_UNAVAILABLE = 'intensify_unavailable'
    INTENSIFY_FAILED = 'intensify_failed'
    EXPEDITION_FAILED = 'expedition_failed'
    BUILD_COLLECT_FAILED = 'build_collect_failed'
    BUILD_START_FAILED = 'build_start_failed'
    REWARD_COLLECT_FAILED = 'reward_collect_failed'
    COOK_FAILED = 'cook_failed'
    DESTROY_FAILED = 'destroy_failed'
    ACQUISITION_FAILED = 'acquisition_failed'

    # 通用
    INVALID_REQUEST = 'invalid_request'
    UNAUTHORIZED = 'unauthorized'
    FORBIDDEN = 'forbidden'
    VALIDATION_ERROR = 'validation_error'
    NOT_FOUND = 'not_found'
    CONFLICT = 'conflict'
    INTERNAL_ERROR = 'internal_error'
    BAD_GATEWAY = 'bad_gateway'
    SERVICE_UNAVAILABLE = 'service_unavailable'
    GATEWAY_TIMEOUT = 'gateway_timeout'
    HTTP_ERROR = 'http_error'


_FALLBACK_ERROR_CODES: dict[int, ErrorCode] = {
    400: ErrorCode.INVALID_REQUEST,
    401: ErrorCode.UNAUTHORIZED,
    403: ErrorCode.FORBIDDEN,
    404: ErrorCode.NOT_FOUND,
    409: ErrorCode.CONFLICT,
    422: ErrorCode.VALIDATION_ERROR,
    429: ErrorCode.CONFLICT,
    500: ErrorCode.INTERNAL_ERROR,
    502: ErrorCode.BAD_GATEWAY,
    503: ErrorCode.SERVICE_UNAVAILABLE,
    504: ErrorCode.GATEWAY_TIMEOUT,
}


def fallback_error_code(status_code: int) -> ErrorCode:
    """没有显式 ``error_code`` 时，按 HTTP 状态码给出稳定兜底码。"""
    return _FALLBACK_ERROR_CODES.get(int(status_code), ErrorCode.HTTP_ERROR)


class ApiError(HTTPException):
    """携带结构化 ``error_code`` 的 HTTP 异常。

    ``detail`` 保持字符串，既让 FastAPI 默认错误体可读，也避免破坏依赖
    ``str(exc.detail)`` 的既有测试。统一的异常处理器会把 ``error_code``
    写进 JSON 响应体。
    """

    def __init__(
        self,
        status_code: int,
        error_code: ErrorCode | str,
        message: str,
        *,
        headers: dict[str, str] | None = None,
        data: Any = None,
    ) -> None:
        super().__init__(status_code=status_code, detail=message, headers=headers)
        self.error_code = str(error_code)
        self.data = data


def api_error(
    status_code: int,
    error_code: ErrorCode | str,
    message: str,
    *,
    headers: dict[str, str] | None = None,
    data: Any = None,
) -> ApiError:
    """构造 :class:`ApiError`，供路由 ``raise api_error(...)`` 直接使用。"""
    return ApiError(
        status_code=status_code,
        error_code=error_code,
        message=message,
        headers=headers,
        data=data,
    )
